static inline void actor_forward(const float input[4], float output[2]) {
    float buf_a[16];
    float buf_b[16];
    float* tmp;
    for (int i = 0; i < 4; i++) buf_a[i] = input[i];

    float* src = buf_a;
    float* dst = buf_b;

    // --- Layer 0 ---
    for (int j = 0; j < 16; j++) {
        float sum = L0_BIASES[j];
        for (int k = 0; k < 4; k++) {
            sum += src[k] * L0_WEIGHTS[k * 16 + j];
        }
        dst[j] = tanhf(sum);
    }
    tmp = src; src = dst; dst = tmp;

    // --- Layer 1 ---
    for (int j = 0; j < 16; j++) {
        float sum = L1_BIASES[j];
        for (int k = 0; k < 16; k++) {
            sum += src[k] * L1_WEIGHTS[k * 16 + j];
        }
        dst[j] = tanhf(sum);
    }
    tmp = src; src = dst; dst = tmp;

    // --- Layer 2 ---
    for (int j = 0; j < 2; j++) {
        float sum = L2_BIASES[j];
        for (int k = 0; k < 16; k++) {
            sum += src[k] * L2_WEIGHTS[k * 2 + j];
        }
        dst[j] = sum;
    }

    for (int i = 0; i < 2; i++) output[i] = dst[i];
}

